import {createStructuredConsumerAdapter} from '../../../adapters/structured-documents.js';
import {FIXTURES,STRUCTURE_TREE,NOTE_FIXTURES} from '../../../adapters/library-fixtures.js';
import {SemanticCommandBus} from '../../../foundation/global/commands.js';
import {GlobalInputKeymapOwner} from '../../../foundation/global/input-keymap.js';
import {StructuredSurfaceHost} from '../../../foundation/structured/surface-host.js';

const bundle={initialDocumentId:'KU-D05-0021',FIXTURES,STRUCTURE_TREE,NOTE_FIXTURES};
const assert=(condition,message)=>{if(!condition)throw Error(message)};
const adapter=createStructuredConsumerAdapter('library',bundle),commands=new SemanticCommandBus(),globalInputKeymapOwner=new GlobalInputKeymapOwner({commands}),host=new StructuredSurfaceHost({adapter,commands,globalInputKeymapOwner});
const root=document.querySelector('#surface');let chooserCount=0;root.addEventListener('structured-insertion-request',()=>chooserCount++);host.renderInto(root);
const steps=[];
const capture=(id,fn)=>{try{steps.push({id,status:'PASS',evidence:fn()})}catch(error){steps.push({id,status:'FAIL',error:String(error?.stack||error)})}};

capture('browser.primary-left-click-opens-chooser-no-mutation',()=>{const before=JSON.stringify(adapter.snapshot()),tx=adapter.transactionDescriptor(),plus=root.querySelector('[data-structured-gap-key="ROOT::1::0"] [data-structured-insertion-trigger="true"]');assert(plus,'gap plus missing');plus.dispatchEvent(new MouseEvent('click',{bubbles:true,cancelable:true,button:0}));const afterTx=adapter.transactionDescriptor();assert(chooserCount===1&&before===JSON.stringify(adapter.snapshot())&&afterTx.historyLength===tx.historyLength,'left click route drift');return {chooserCount,documentUnchanged:true,historyDelta:0};});
capture('browser.keyboard-enter-opens-chooser-no-mutation',()=>{const before=JSON.stringify(adapter.snapshot()),tx=adapter.transactionDescriptor(),plus=root.querySelector('[data-structured-gap-key="ROOT::1::0"] [data-structured-insertion-trigger="true"]');plus.focus();plus.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',code:'Enter',bubbles:true,cancelable:true}));const afterTx=adapter.transactionDescriptor();assert(chooserCount===2&&before===JSON.stringify(adapter.snapshot())&&afterTx.historyLength===tx.historyLength,'keyboard chooser route drift');return {chooserCount,activeElementIsGap:document.activeElement===plus,documentUnchanged:true,historyDelta:0};});
capture('browser.secondary-right-click-direct-paragraph-exact-gap',()=>{const before=adapter.snapshot(),tx=adapter.transactionDescriptor(),plus=root.querySelector('[data-structured-gap-key="ROOT::1::0"] [data-structured-insertion-trigger="true"]'),event=new MouseEvent('contextmenu',{bubbles:true,cancelable:true,button:2});plus.dispatchEvent(event);const after=adapter.snapshot(),afterTx=adapter.transactionDescriptor();assert(event.defaultPrevented&&chooserCount===2,'right click incorrectly opened chooser/default menu');assert(after.blocks.length===before.blocks.length+1&&after.blocks[1]?.type==='paragraph'&&after.blocks[1]?.html===''&&after.blocks[0]?.id===before.blocks[0]?.id&&after.blocks[2]?.id===before.blocks[1]?.id,'right click did not insert exact-gap paragraph');assert(afterTx.historyLength===tx.historyLength+1&&afterTx.workingRevision===tx.workingRevision+1,'right click not atomic');assert(root.querySelectorAll('[data-structured-insertion-trigger="true"]').length>0,'surface did not rerender after direct insertion');return {defaultPrevented:event.defaultPrevented,chooserCount,insertedId:after.blocks[1].id,insertedType:after.blocks[1].type,exactGap:true,historyDelta:1,workingRevisionDelta:1,rerendered:true};});
capture('browser.route-metadata-present',()=>{const plus=root.querySelector('[data-structured-insertion-trigger="true"]');assert(plus?.dataset.structuredPrimaryAction==='chooser'&&plus?.dataset.structuredKeyboardAction==='chooser'&&plus?.dataset.structuredSecondaryAction==='insert-paragraph','interaction metadata mismatch');return {primary:plus.dataset.structuredPrimaryAction,keyboard:plus.dataset.structuredKeyboardAction,secondary:plus.dataset.structuredSecondaryAction};});

const failed=steps.filter(step=>step.status!=='PASS');globalThis.S01BrowserProof={status:failed.length?'FAIL':'PASS',kind:'OD057_S01_BROWSER_POINTER_KEYBOARD_PROOF',chooserCount,steps};
document.querySelector('#status').textContent=globalThis.S01BrowserProof.status;
